func (mb *MetricsBuilder) RecordK8sPodMemoryLimitDataPoint(ts pcommon.Timestamp, val int64, memoryLimitTypeAttributeValue AttributeMemoryLimitType) {
	mb.metricK8sPodMemoryLimit.recordDataPoint(mb.startTime, ts, val, memoryLimitTypeAttributeValue.String())
}

// RecordK8sPodMemoryPressureStallTimeDataPoint adds a data point to k8s.pod.memory.pressure.stall_time metric.
func (mb *MetricsBuilder) RecordK8sPodMemoryPressureStallTimeDataPoint(ts pcommon.Timestamp, val float64, pressureStallTypeAttributeValue AttributePressureStallType) {
	mb.metricK8sPodMemoryPressureStallTime.recordDataPoint(mb.startTime, ts, val, pressureStallTypeAttributeValue.String())
}

// Reset resets metrics builder to its initial state. It should be used when external metrics source is restarted,
// and metrics builder should update its startTime and reset it's internal state accordingly.
func (mb *MetricsBuilder) Reset(options ...MetricBuilderOption) {
	mb.startTime = pcommon.NewTimestampFromTime(time.Now())
	for _, op := range options {
		op.apply(mb)
	}
}
